"""Validation for generated ICS byte streams."""

from icalendar import Calendar

from panorama_calendar.ics.folding import CRLF


class ICSValidationError(ValueError):
    """Raised when generated bytes violate output invariants."""


def validate_ics_bytes(data: bytes) -> None:
    """Validate CRLF, physical line widths, UTF-8 and iCalendar parsing."""
    if not data:
        raise ICSValidationError("ICS output is empty")
    if data.startswith(b"\xef\xbb\xbf"):
        raise ICSValidationError("ICS output must not contain a UTF-8 BOM")
    if not data.endswith(CRLF):
        raise ICSValidationError("ICS output must end with CRLF")

    without_crlf = data.replace(CRLF, b"")
    if b"\r" in without_crlf or b"\n" in without_crlf:
        raise ICSValidationError("ICS output contains an isolated CR or LF")

    physical_lines = data[:-2].split(CRLF)
    for line in physical_lines:
        if len(line) > 75:
            raise ICSValidationError(f"physical line exceeds 75 octets: {len(line)}")

    try:
        data.decode("utf-8", errors="strict")
    except UnicodeDecodeError as error:
        raise ICSValidationError("ICS output is not valid UTF-8") from error

    try:
        calendar = Calendar.from_ical(data)
    except Exception as error:
        raise ICSValidationError("ICS output cannot be parsed") from error
    if calendar.get("VERSION") != "2.0":
        raise ICSValidationError("VCALENDAR VERSION must be 2.0")
